// How many of each kind of gear are out over the open loans in the list. Neither the loans nor the list are changed.
export function stillOut(loans: Loan[]): Record<GearKind, number> {
    const totals: Record<GearKind, number> = {
        boatKey: 0,
        windlass: 0,
        lifejacket: 0,
        mooringPin: 0,
        mallet: 0,
        waterKey: 0,
    };
    for (const loan of loans) {
        if (!isOpen(loan)) continue;
        for (const line of loan.lines) {
            totals[line.kind] += line.issued - line.back;
        }
    }
    return totals;
}

